export type SpeechTurn = {
  /**
   * @description Delivery instructions for this turn, such as tone, pacing, or emotion. Overrides the top-level `instructions`.
   * @example whispering
   * @type string | undefined
   */
  instructions?: string
  /**
   * @description Text to synthesize
   * @example Hi Jane.
   * @type string
   */
  text: string
  /**
   * @description Voice for this turn. Defaults to the top-level `voice`.
   * @minLength 1
   * @example Kore
   * @type string | undefined
   */
  voice?: string
}

/**
 * @description Text to synthesize, or a list of turns for multi-speaker input. Each turn has its own text, voice, and instructions. Multi-speaker input is supported by Gemini TTS models and by Fish Audio models other than S1.
 * @example Hello world
 */
export type SpeechInput = string | SpeechTurn[]

/**
 * @description Reference audio input object
 * @example {"data":"data:audio/wav;base64,UklGRuQXDABXQVZF..."}
 * @type object
 */
export type SpeechInputReferenceAudioInput = {
  /**
   * @description Base64-encoded reference audio (optionally a data URI). Supported audio formats are provider-specific. Limited to 20 MiB of base64 (15 MiB of decoded audio). Exactly one of `data` or `url` is required.
   * @minLength 1
   * @maxLength 20971520
   * @example data:audio/wav;base64,UklGRuQXDABXQVZF...
   * @type string | undefined
   */
  data?: string
  /**
   * @description Audio format of the reference audio (e.g., wav, mp3). Optional; most providers detect the format from the audio bytes.
   * @example wav
   * @type string | undefined
   */
  format?: string
  /**
   * @description Public http(s) URL of the reference audio. OpenRouter downloads it (15 MiB max) and forwards the bytes, never the URL. Exactly one of `data` or `url` is required.
   *
   * Format: `uri`
   * @maxLength 2048
   * @example https://example.com/reference.wav
   * @type string | undefined
   */
  url?: string
}

/**
 * @description Reference audio input for stateless voice cloning. Up to three parts per request; the Nth audio part is addressable from `input` as `@AudioN` on providers that support multiple references.
 * @example {"input_audio":{"data":"data:audio/wav;base64,UklGRuQXDABXQVZF..."},"type":"input_audio"}
 * @type object
 */
export type SpeechInputReferenceAudio = {
  /**
   * @description Reference audio input object
   * @example {"data":"data:audio/wav;base64,UklGRuQXDABXQVZF..."}
   * @type object
   */
  input_audio: SpeechInputReferenceAudioInput
  type: 'input_audio'
}

/**
 * @description Transcript of an `input_audio` part
 * @example {"text":"I used to rule the world.","type":"text"}
 * @type object
 */
export type SpeechInputReferenceText = {
  /**
   * @description Transcript of an `input_audio` part. With a single clip it may appear before or after the clip; with multiple clips it must immediately follow the clip it transcribes.
   * @maxLength 10000
   * @example I used to rule the world.
   * @type string
   */
  text: string
  type: 'text'
}

/**
 * @description Reference image input object
 * @example {"url":"data:image/png;base64,iVBORw0KGgo..."}
 * @type object
 */
export type SpeechInputReferenceImageInput = {
  /**
   * @description JPEG, PNG, or WebP reference image as a base64 data URI or a public http(s) URL. Remote images are downloaded (15 MiB max) and forwarded as bytes, never as the URL.
   * @minLength 1
   * @maxLength 20971520
   * @example data:image/png;base64,iVBORw0KGgo...
   * @type string
   */
  url: string
}

/**
 * @description Reference image. On its own it describes the desired voice (voice design); alongside an `input_audio` part it is a scene image describing the setting the cloned voice speaks in. At most one per request. Only routed to endpoints that support image references.
 * @example {"image_url":{"url":"data:image/png;base64,iVBORw0KGgo..."},"type":"image_url"}
 * @type object
 */
export type SpeechInputReferenceImage = {
  /**
   * @description Reference image input object
   * @example {"url":"data:image/png;base64,iVBORw0KGgo..."}
   * @type object
   */
  image_url: SpeechInputReferenceImageInput
  type: 'image_url'
}

/**
 * @description Reference content part for stateless voice cloning or voice design
 * @example {"input_audio":{"data":"data:audio/wav;base64,UklGRuQXDABXQVZF..."},"type":"input_audio"}
 */
export type SpeechInputReference =
  | (SpeechInputReferenceAudio & {
      type: 'input_audio'
    })
  | (SpeechInputReferenceText & {
      type: 'text'
    })
  | (SpeechInputReferenceImage & {
      type: 'image_url'
    })

/**
 * @description Metadata for observability and tracing. Known keys (trace_id, trace_name, span_name, generation_name, parent_span_id) have special handling. Additional keys are passed through as custom metadata to configured broadcast destinations.
 * @example {"trace_id":"trace-abc123","trace_name":"my-app-trace"}
 * @type object
 */
export type TraceConfig = {
  generation_name?: string
  parent_span_id?: string
  span_name?: string
  trace_id?: string
  trace_name?: string
  [key: string]: unknown
}

/**
 * @description A detected entity, returned when the provider runs entity detection
 * @example {"end_char":25,"start_char":15,"text":"John Smith","type":"name"}
 * @type object
 */
export type STTEntity = {
  /**
   * @description Zero-based exclusive character offset of the entity end within the response-level text (not seconds)
   * @example 25
   * @type integer
   */
  end_char: number
  /**
   * @description Zero-based character offset of the entity start within the response-level text (not seconds)
   * @example 15
   * @type integer
   */
  start_char: number
  /**
   * @description Entity text as it appears in the transcript
   * @type string
   */
  text: string
  /**
   * @description Provider entity type label
   * @example name
   * @type string
   */
  type: string
}

/**
 * @description A timestamped transcript segment, returned when response_format is verbose_json
 * @example {"avg_logprob":-0.28,"compression_ratio":1.13,"end":3.2,"id":0,"no_speech_prob":0.01,"seek":0,"speaker":0,"start":0,"temperature":0,"text":"Hello there.","tokens":[50364,2425,456]}
 * @type object
 */
export type STTSegment = {
  /**
   * @description Average log probability of the segment
   *
   * Format: `double`
   * @type number | undefined
   */
  avg_logprob?: number
  /**
   * @description Zero-based audio channel index for the segment, present when the provider transcribes channels separately
   * @example 0
   * @type integer | undefined
   */
  channel?: number
  /**
   * @description Compression ratio of the segment
   *
   * Format: `double`
   * @type number | undefined
   */
  compression_ratio?: number
  /**
   * @description Segment end time in seconds
   *
   * Format: `double`
   * @example 3.2
   * @type number
   */
  end: number
  /**
   * @description Segment index within the transcript
   * @example 0
   * @type integer
   */
  id: number
  /**
   * @description Probability the segment contains no speech
   *
   * Format: `double`
   * @type number | undefined
   */
  no_speech_prob?: number
  /**
   * @description Seek offset of the segment
   * @example 0
   * @type integer | undefined
   */
  seek?: number
  /**
   * @description Speaker index for the segment, present when the provider returns diarization data
   * @example 0
   * @type integer | undefined
   */
  speaker?: number
  /**
   * @description Provider speaker label for the segment, present when the provider labels speakers with a string
   * @example speaker_0
   * @type string | undefined
   */
  speaker_label?: string
  /**
   * @description Segment start time in seconds
   *
   * Format: `double`
   * @example 0
   * @type number
   */
  start: number
  /**
   * @description Temperature used for the segment
   *
   * Format: `double`
   * @type number | undefined
   */
  temperature?: number
  /**
   * @description Transcribed text of the segment
   * @example Hello there.
   * @type string
   */
  text: string
  /**
   * @description Token IDs of the segment
   * @type array | undefined
   */
  tokens?: number[]
}

/**
 * @description Aggregated usage statistics for the request
 * @example {"cost":0.000508,"input_tokens":83,"output_tokens":30,"seconds":9.2,"total_tokens":113}
 * @type object
 */
export type STTUsage = {
  /**
   * @description Total cost of the request in USD
   *
   * Format: `double`
   * @example 0.000508
   * @type number | undefined
   */
  cost?: number
  /**
   * @description Number of input tokens billed for this request
   * @example 83
   * @type integer | undefined
   */
  input_tokens?: number
  /**
   * @description Number of output tokens generated
   * @example 30
   * @type integer | undefined
   */
  output_tokens?: number
  /**
   * @description Duration of the input audio in seconds
   *
   * Format: `double`
   * @example 9.2
   * @type number | undefined
   */
  seconds?: number
  /**
   * @description Total number of tokens used (input + output)
   * @example 113
   * @type integer | undefined
   */
  total_tokens?: number
}

