export type ArmorRule = {
  /**
   * @description Stable id, unique within its source; reported as the deciding rule when it fires.
   * @minLength 1
   * @maxLength 64
   * @pattern ^[a-z0-9][a-z0-9_-]*$
   * @type string
   */
  id: string
  /**
   * @description What the rule matches, written for the classifier.
   * @minLength 1
   * @maxLength 8000
   * @type string
   */
  instructions: string
  /**
   * @description Display name shown in verdict explanations; defaults to the id.
   * @minLength 1
   * @maxLength 120
   * @type string | undefined
   */
  name?: string
  /**
   * @description Probability at or above which the rule counts as matched. Defaults to 0.6 for hard-deny and soft-deny rules and 0.7 for allow rules (an exception needs stronger evidence to clear a matched soft deny).
   *
   * Format: `double`
   * @type number | undefined
   */
  threshold?: number
}

export type ArmorEnvironmentEntry = {
  /**
   * @minLength 1
   * @maxLength 120
   * @type string
   */
  name: string
  /**
   * @maxLength 4000
   * @type string
   */
  value: string
}

export type ArmorAutoMode = {
  allow?: (string | ArmorRule)[]
  environment?: (string | ArmorEnvironmentEntry)[]
  hard_deny?: (string | ArmorRule)[]
  soft_deny?: (string | ArmorRule)[]
}

/**
 * @description The Armor context: Claude Code's `classifier_context` (v1), with `auto_mode.{hard_deny,soft_deny,allow}` rules as strings or `{ id, instructions, threshold? }` objects and `auto_mode.environment` entries as `"Name: value"` strings or `{ name, value }` objects. `threshold` applies when Armor evaluates; when the provider evaluates natively (Anthropic dangerous-tool-use beta) rules are judged at the provider's own boundary.
 * @example {"auto_mode":{"allow":[],"environment":["Trusted repo: github.com/acme/app"],"hard_deny":[],"soft_deny":[{"id":"secrets-in-vcs","instructions":"Staging, committing or pushing a file that holds secrets, including indirectly through git add -A when the tree shows one."}]},"v":1}
 * @type object
 */
export type ArmorContext = {
  auto_mode?: ArmorAutoMode
  v: 1
  [key: string]: unknown
}

export const armorPluginModeEnum = {
  enforce: 'enforce',
  audit: 'audit',
} as const

export type ArmorPluginModeEnumKey =
  (typeof armorPluginModeEnum)[keyof typeof armorPluginModeEnum]

export const armorPluginOnErrorEnum = {
  log: 'log',
  block: 'block',
} as const

export type ArmorPluginOnErrorEnumKey =
  (typeof armorPluginOnErrorEnum)[keyof typeof armorPluginOnErrorEnum]

export const armorPluginOutputModeEnum = {
  text: 'text',
  custom_item: 'custom_item',
  claude_code_compatibility: 'claude_code_compatibility',
} as const

export type ArmorPluginOutputModeEnumKey =
  (typeof armorPluginOutputModeEnum)[keyof typeof armorPluginOutputModeEnum]

/**
 * @description Evaluates every client tool call the model emits against a rule stack (hard-deny, soft-deny, allow) before it reaches the caller. The stack merges the workspace guardrail, this plugin, and any Anthropic `safeguards`; on endpoints that support Anthropic's `dangerous-tool-use` beta the evaluation is native, elsewhere it is one decisions call per tool call. Evaluation is not billed during the beta. Verdicts are reported as `safeguard_results`.
 * @example {"classifier_context":{"auto_mode":{"environment":["Trusted repo: github.com/acme/app"],"soft_deny":[{"id":"no-migrations-delete","instructions":"Deleting a file under db/migrations."}]},"v":1},"id":"armor","use_cc_style_default_rules":true}
 * @type object
 */
export type ArmorPlugin = {
  /**
   * @description The Armor context: Claude Code's `classifier_context` (v1), with `auto_mode.{hard_deny,soft_deny,allow}` rules as strings or `{ id, instructions, threshold? }` objects and `auto_mode.environment` entries as `"Name: value"` strings or `{ name, value }` objects. `threshold` applies when Armor evaluates; when the provider evaluates natively (Anthropic dangerous-tool-use beta) rules are judged at the provider's own boundary.
   * @example {"auto_mode":{"allow":[],"environment":["Trusted repo: github.com/acme/app"],"hard_deny":[],"soft_deny":[{"id":"secrets-in-vcs","instructions":"Staging, committing or pushing a file that holds secrets, including indirectly through git add -A when the tree shows one."}]},"v":1}
   * @type object | undefined
   */
  classifier_context?: ArmorContext
  /**
   * @description Set to false to disable Armor for this request. Defaults to true.
   * @type boolean | undefined
   */
  enabled?: boolean
  /**
   * @description Run provider-native server tools (web search, code execution, ...) through the agent loop so Armor evaluates them too. Defaults to false: native passthrough stands and such calls are reported `skipped`.
   * @type boolean | undefined
   */
  evaluate_native_tools?: boolean
  id: 'armor'
  /**
   * @description `enforce` withholds blocked calls; `audit` evaluates and reports the same verdicts without withholding any calls, regardless of `on_error`. Default `enforce`.
   * @type string | undefined
   */
  mode?: ArmorPluginModeEnumKey
  /**
   * @description When the classifier cannot answer (timeout, upstream error, context too long) the call is reported `unavailable`; `block` rejects it and `log` releases it. Default `block`.
   * @type string | undefined
   */
  on_error?: ArmorPluginOnErrorEnumKey
  /**
   * @description How a blocked call reaches the caller. `text` (the default): the call is withheld and an `<openrouter_armor_blocked>` marker stands in assistant text. `custom_item` (Responses API only): the call is withheld and an `openrouter:armor_blocked` output item carries its id, name, arguments and the rule that fired. `claude_code_compatibility` (Messages API only; the default when the request carries a `dangerous_tool_use` safeguard, i.e. the client speaks Claude Code's protocol): the `tool_use` stays in `content[]` and the verdict is `flagged` in `safeguard_results`, so the client withholds execution and writes the error tool result as under the native classifier. Under `text` and `custom_item` the model received a failure result in the loop and continued in the same request; under `claude_code_compatibility` the turn ends on the flagged call and the model continues on the next request, after the client's denial.
   * @type string | undefined
   */
  output_mode?: ArmorPluginOutputModeEnumKey
  /**
   * @description Prepend Claude Code's built-in auto-mode rule set (1 hard-deny, 72 soft-deny, 17 allow, 21 environment slots) ahead of every configured rule. Defaults to true on the Anthropic Messages API and false elsewhere.
   * @type boolean | undefined
   */
  use_cc_style_default_rules?: boolean
}

export const autoBetaRouterPluginCostTierEnum = {
  low: 'low',
  medium: 'medium',
  high: 'high',
  xhigh: 'xhigh',
  max: 'max',
} as const

export type AutoBetaRouterPluginCostTierEnumKey =
  (typeof autoBetaRouterPluginCostTierEnum)[keyof typeof autoBetaRouterPluginCostTierEnum]

/**
 * @example {"allowed_models":["anthropic/*","openai/*"],"cost_tier":"low","enabled":true,"excluded_models":["openai/gpt-4o"],"id":"auto-beta-router"}
 * @type object
 */
export type AutoBetaRouterPlugin = {
  /**
   * @description List of model patterns to filter which models the auto-beta-router can route between. Supports wildcards (e.g., "anthropic/*" matches all Anthropic models). Up to 1024 patterns, each at most 1024 characters, with 65536 total characters across all patterns. When not specified, every model ranked for the classified task type is a candidate, falling back to a default model set when rankings are unavailable.
   * @example ["anthropic/*","openai/gpt-4o","google/*"]
   * @type array | undefined
   */
  allowed_models?: string[]
  /**
   * @description Deprecated: Use cost_tier instead. Balances routing between cost and quality on a 0-10 scale. The auto-beta-router ranks models for the classified task type by community spend share, then filters candidates by their average cost per generation for that task. Higher values favor cheaper models: 10 keeps only models around the cheapest 10th percentile, while 0 permits models up to the 90th percentile for cost. Defaults to 9 when no cost setting is provided. It remains supported and retains ceiling behavior, but cost_tier takes precedence when both are provided.
   * @deprecated
   * @minimum 0
   * @maximum 10
   * @example 9
   * @type integer | undefined
   */
  cost_quality_tradeoff?: number
  /**
   * @description Named cost/quality setting. For auto-beta-router, tiers select cost-percentile bands: low = [0, 20), medium = [20, 40), high = [40, 60), xhigh = [60, 80), and max = [80, 100]. Takes precedence over the deprecated numeric cost_quality_tradeoff when both are provided.
   * @example low
   * @type string | undefined
   */
  cost_tier?: AutoBetaRouterPluginCostTierEnumKey
  /**
   * @description Set to false to disable the auto-beta-router plugin for this request. Defaults to true.
   * @type boolean | undefined
   */
  enabled?: boolean
  /**
   * @description List of model patterns to exclude from auto-beta-router selection. Supports wildcards (e.g., "meta-llama/*" excludes all Llama models). Up to 1024 patterns, each at most 1024 characters, with 65536 total characters across all patterns. Applied after allowed_models, so an excluded pattern always wins over an allowed one.
   * @example ["openai/gpt-4o","meta-llama/*"]
   * @type array | undefined
   */
  excluded_models?: string[]
  id: 'auto-beta-router'
}

