/**
 * @description Anthropic-style cache breakpoint for the content part. Interchangeable with the OpenAI-style `prompt_cache_breakpoint` marker: OpenRouter converts between the two based on the provider serving the request.
 * @example {"ttl":"5m","type":"ephemeral"}
 */
export type ChatContentCacheControl = AnthropicCacheControlDirective & object

/**
 * @description Marks an explicit prompt-cache boundary on this content block (OpenAI-style). Everything through the block carrying this marker is part of the candidate cached prefix. Supported natively by OpenAI GPT-5.6 and newer; on providers that use Anthropic-style `cache_control`, OpenRouter converts the marker to that format automatically. `ttl` ("30m" or "12h") overrides the request-level `prompt_cache_options.ttl` for this boundary; 12h writes bill at the higher cache-write rate.
 * @example {"mode":"explicit","ttl":"30m"}
 * @type object
 */
export type PromptCacheBreakpoint = {
  mode: 'explicit'
  ttl?: string | null
} | null

/**
 * @description Text content part
 * @example {"text":"Hello, world!","type":"text"}
 * @type object
 */
export type ChatContentText = {
  /**
   * @description Anthropic-style cache breakpoint for the content part. Interchangeable with the OpenAI-style `prompt_cache_breakpoint` marker: OpenRouter converts between the two based on the provider serving the request.
   * @example {"ttl":"5m","type":"ephemeral"}
   */
  cache_control?: ChatContentCacheControl
  /**
   * @description Marks an explicit prompt-cache boundary on this content block (OpenAI-style). Everything through the block carrying this marker is part of the candidate cached prefix. Supported natively by OpenAI GPT-5.6 and newer; on providers that use Anthropic-style `cache_control`, OpenRouter converts the marker to that format automatically. `ttl` ("30m" or "12h") overrides the request-level `prompt_cache_options.ttl` for this boundary; 12h writes bill at the higher cache-write rate.
   * @example {"mode":"explicit","ttl":"30m"}
   * @type object | undefined
   */
  prompt_cache_breakpoint?: PromptCacheBreakpoint | null
  text: string
  type: 'text'
}

