export const subagentReasoningEffortEnum = {
  max: 'max',
  xhigh: 'xhigh',
  high: 'high',
  medium: 'medium',
  low: 'low',
  minimal: 'minimal',
  none: 'none',
} as const

export type SubagentReasoningEffortEnumKey =
  (typeof subagentReasoningEffortEnum)[keyof typeof subagentReasoningEffortEnum]

/**
 * @description Reasoning configuration forwarded to the subagent call. Use this to control reasoning effort and token budget for models that support extended thinking.
 * @example {"effort":"low"}
 * @type object
 */
export type SubagentReasoning = {
  /**
   * @description Reasoning effort level for the subagent call.
   * @type string | undefined
   */
  effort?: SubagentReasoningEffortEnumKey
  /**
   * @description Maximum number of reasoning tokens the subagent may use. Forwarded to the subagent call as `reasoning.max_tokens`.
   * @type integer | undefined
   */
  max_tokens?: number
}

/**
 * @description A tool made available to the subagent. Only OpenRouter server tools (e.g. openrouter:web_search) are supported; function tools are rejected because the worker has no way to execute them. The subagent tool may not list itself.
 * @example {"type":"openrouter:web_search"}
 * @type object
 */
export type SubagentNestedTool = {
  parameters?: {
    [key: string]: unknown
  }
  type: string
  [key: string]: unknown
}

/**
 * @description Configuration for one openrouter:subagent server tool entry.
 * @example {"model":"~anthropic/claude-haiku-latest","name":"summarizer"}
 * @type object
 */
export type SubagentServerToolConfig = {
  /**
   * @description EXPERIMENTAL — subject to change without notice. When true, the subagent inherits every client function defined in the request's top-level `tools` list. Supported on the Responses API (`/api/v1/responses`) only; other APIs reject it with a `400`.
   * @example true
   * @type boolean | undefined
   */
  inherit_functions?: boolean
  /**
   * @description EXPERIMENTAL — subject to change without notice. Names of the top-level function tools that the subagent will inherit. Any tool that matches by name will be copied fully into the tools array of the subagent. When `inherit_functions` is `true`, this list does nothing, because every client function will be inherited by default. Names are trimmed before validation, so a whitespace-only name is rejected with a `400`. Supported on the Responses API (`/api/v1/responses`) only; other APIs reject it with a `400`.
   * @example ["lookup_order"]
   * @type array | undefined
   */
  inherited_function_names?: string[]
  /**
   * @description System instructions for the subagent. When omitted, the subagent responds with no system prompt of its own.
   * @example You are a fast, focused worker. Complete the task exactly as described.
   * @type string | undefined
   */
  instructions?: string
  /**
   * @description Maximum number of output tokens (including reasoning) the subagent may produce. When omitted, the provider's default applies.
   * @example 2048
   * @type integer | undefined
   */
  max_completion_tokens?: number
  /**
   * @description Maximum number of tool-calling steps the subagent may take during its agentic loop. Capped at 25. Only relevant when the subagent is given tools. Forwarded to the subagent call as `max_tool_calls`.
   * @minimum 1
   * @maximum 25
   * @example 5
   * @type integer | undefined
   */
  max_tool_calls?: number
  /**
   * @description Slug of the model that executes delegated tasks (any OpenRouter model). Typically a smaller, cheaper, faster model than the one delegating. When omitted, the model from the outer API request is used. The subagent tool itself cannot be the subagent model.
   * @example ~anthropic/claude-haiku-latest
   * @type string | undefined
   */
  model?: string
  /**
   * @description Optional name for this subagent. The model sees one tool per named subagent (and one default for an unnamed entry). Names must be unique across subagent entries. Letters, digits, spaces, underscores, and dashes; trimmed; 1–64 chars.
   * @minLength 1
   * @maxLength 64
   * @pattern ^[a-zA-Z0-9 _-]+$
   * @example summarizer
   * @type string | undefined
   */
  name?: string
  /**
   * @description Reasoning configuration forwarded to the subagent call. Use this to control reasoning effort and token budget for models that support extended thinking.
   * @example {"effort":"low"}
   * @type object | undefined
   */
  reasoning?: SubagentReasoning
  /**
   * @description Sampling temperature forwarded to the subagent call. When omitted, the provider's default applies.
   *
   * Format: `double`
   * @example 0.7
   * @type number | undefined
   */
  temperature?: number
  /**
   * @description Tools the subagent may use while executing a delegated task. The subagent runs as an agentic sub-agent over these tools, then returns its outcome. Only OpenRouter server tools are supported — function tools are rejected — and the list must not include the subagent tool itself.
   * @type array | undefined
   */
  tools?: SubagentNestedTool[]
}

/**
 * @description OpenRouter built-in server tool: delegates self-contained tasks to a smaller, cheaper, faster worker model (any OpenRouter model) mid-generation and returns its outcome. The worker may run as a sub-agent with its own tools.
 * @example {"parameters":{"model":"~anthropic/claude-haiku-latest"},"type":"openrouter:subagent"}
 * @type object
 */
export type SubagentServerToolOpenRouter = {
  /**
   * @description Configuration for one openrouter:subagent server tool entry.
   * @example {"model":"~anthropic/claude-haiku-latest","name":"summarizer"}
   * @type object | undefined
   */
  parameters?: SubagentServerToolConfig
  type: 'openrouter:subagent'
}

