/**
 * @description Tool definition for function calling (regular function or OpenRouter built-in server tool)
 * @example {"function":{"description":"Get the current weather for a location","name":"get_weather","parameters":{"properties":{"location":{"description":"City name","type":"string"},"unit":{"enum":["celsius","fahrenheit"],"type":"string","x-speakeasy-unknown-values":"allow"}},"required":["location"],"type":"object"}},"type":"function"}
 */
export type ChatFunctionTool =
  | {
      /**
       * @description Anthropic-style cache breakpoint for the content part. Interchangeable with the OpenAI-style `prompt_cache_breakpoint` marker: OpenRouter converts between the two based on the provider serving the request.
       * @example {"ttl":"5m","type":"ephemeral"}
       */
      cache_control?: ChatContentCacheControl
      defer_loading?: boolean
      /**
       * @description Function definition for tool calling
       * @example {"description":"Get the current weather for a location","name":"get_weather","parameters":{"properties":{"location":{"description":"City name","type":"string"}},"required":["location"],"type":"object"}}
       * @type object
       */
      function: {
        defer_loading?: boolean
        /**
         * @description Function description for the model
         * @example Get the current weather for a location
         * @type string | undefined
         */
        description?: string
        /**
         * @description Function name (a-z, A-Z, 0-9, underscores, dashes, max 64 chars)
         * @maxLength 64
         * @example get_weather
         * @type string
         */
        name: string
        /**
         * @description Function parameters as JSON Schema object
         * @example {"properties":{"location":{"description":"City name","type":"string"}},"required":["location"],"type":"object"}
         * @type object | undefined
         */
        parameters?: {
          [key: string]: unknown
        }
        /**
         * @description Enable strict schema adherence
         * @example false
         * @type boolean | undefined
         */
        strict?: boolean | null
      }
      type: 'function'
    }
  | AdvisorServerToolOpenRouter
  | BashServerTool
  | DatetimeServerTool
  | FilesServerTool
  | FusionServerToolOpenRouter
  | ImageGenerationServerToolOpenRouter
  | ChatSearchModelsServerTool
  | SubagentServerToolOpenRouter
  | WebFetchServerTool
  | OpenRouterWebSearchServerTool
  | ChatWebSearchShorthand
  | ChatDynamicServerTool

/**
 * @description System message for setting behavior
 * @example {"content":"You are a helpful assistant.","name":"Assistant Config","role":"system"}
 * @type object
 */
export type ChatSystemMessage = {
  /**
   * @description OpenRouter extension. Changes reasoning effort from this point in the conversation onward without invalidating the prompt cache for the preceding turns. Place it on a content-less system message (`content: ""`) directly before the user message it should apply to, and keep it at that position in later requests. Equivalent to the OpenAI Responses `configuration_update` input item and the Anthropic Messages per-message `output_config.effort`.
   * @example {"reasoning":{"effort":"low"}}
   */
  configuration_update?: ConfigurationUpdate | null
  /**
   * @description System message content
   * @example You are a helpful assistant.
   */
  content: string | ChatContentText[]
  /**
   * @description Optional name for the system message
   * @example Assistant Config
   * @type string | undefined
   */
  name?: string
  role: 'system'
}

/**
 * @description User message
 * @example {"content":"What is the capital of France?","role":"user"}
 * @type object
 */
export type ChatUserMessage = {
  /**
   * @description User message content
   * @example What is the capital of France?
   */
  content: string | ChatContentItems[]
  /**
   * @description Optional name for the user
   * @example User
   * @type string | undefined
   */
  name?: string
  role: 'user'
}

/**
 * @description Tool response message
 * @example {"content":"The weather in San Francisco is 72°F and sunny.","role":"tool","tool_call_id":"call_abc123"}
 * @type object
 */
export type ChatToolMessage = {
  /**
   * @description Tool response content
   * @example The weather in San Francisco is 72°F and sunny.
   */
  content: string | ChatContentItems[]
  role: 'tool'
  /**
   * @description ID of the assistant message tool call this message responds to
   * @example call_abc123
   * @type string
   */
  tool_call_id: string
}

/**
 * @description Chat completion message with role-based discrimination
 * @example {"content":"What is the capital of France?","role":"user"}
 */
export type ChatMessages =
  | (ChatSystemMessage & {
      role: 'system'
    })
  | (ChatUserMessage & {
      role: 'user'
    })
  | (ChatDeveloperMessage & {
      role: 'developer'
    })
  | (ChatAssistantMessage & {
      role: 'assistant'
    })
  | (ChatToolMessage & {
      role: 'tool'
    })

