export const fusionPluginPresetEnum = {
  'general-high': 'general-high',
  'general-budget': 'general-budget',
  'general-fast': 'general-fast',
} as const

export type FusionPluginPresetEnumKey =
  (typeof fusionPluginPresetEnum)[keyof typeof fusionPluginPresetEnum]

/**
 * @example {"analysis_models":["~anthropic/claude-opus-latest","~openai/gpt-sol-latest","~google/gemini-pro-latest"],"enabled":true,"id":"fusion","model":"~anthropic/claude-opus-latest"}
 * @type object
 */
export type FusionPlugin = {
  /**
   * @description For a Fusion run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool, slugs of models to run in parallel as the "expert panel" the analyst analyzes. Each model receives the same user prompt with web_search + web_fetch enabled. Capped at 8 models to bound cost amplification. When omitted, defaults to the Quality preset from the /labs/fusion UI (~anthropic/claude-opus-latest, ~openai/gpt-sol-latest, ~google/gemini-pro-latest).
   * @example ["~anthropic/claude-opus-latest","~openai/gpt-sol-latest","~google/gemini-pro-latest"]
   * @type array | undefined
   */
  analysis_models?: string[]
  /**
   * @description Set to false to disable Fusion configuration for a run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool. Defaults to true.
   * @type boolean | undefined
   */
  enabled?: boolean
  id: 'fusion'
  /**
   * @description For a Fusion run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool, the maximum number of tool-calling steps each panelist (analysis model) and the analyst model may take during their agentic web-research loop. Models with web_search/web_fetch enabled iterate until they produce a text response or hit this ceiling. Defaults to 4. Capped at 16.
   * @minimum 1
   * @maximum 16
   * @example 12
   * @type integer | undefined
   */
  max_tool_calls?: number
  /**
   * @description For a Fusion run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool, the slug of the model that performs both the analyst step (with web_search + web_fetch) and the final synthesis. When omitted, defaults to the first model in the Quality preset.
   * @example ~anthropic/claude-opus-latest
   * @type string | undefined
   */
  model?: string
  /**
   * @description Configuration for a Fusion run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool. A curated OpenRouter preset (slugs follow `<task>-<tier>`, e.g. `general-high`). Expands server-side into the preset's analysis_models panel and analyst model, so callers never name individual models. Explicitly provided `analysis_models` / `model` take precedence.
   * @example general-high
   * @type string | undefined
   */
  preset?: FusionPluginPresetEnumKey
  /**
   * @description For a Fusion run started by the `openrouter/fusion` model slug or `openrouter:fusion` server tool, server tools available to panelist and analyst inner calls. Each entry uses the same `{ type, parameters? }` shorthand as the outer Chat Completions request. When omitted, defaults to `[{ type: "openrouter:web_search" }, { type: "openrouter:web_fetch" }]`. Pass an empty array to disable tools entirely (panelists answer from parametric knowledge only).
   * @example [{"parameters":{"excluded_domains":["example.com"]},"type":"openrouter:web_search"},{"type":"openrouter:web_fetch"}]
   * @type array | undefined
   */
  tools?: {
    /**
     * @description Optional configuration forwarded as the tool's `parameters` object.
     * @type object | undefined
     */
    parameters?: {
      [key: string]:
        | string
        | number
        | boolean
        | null
        | (string | number | boolean | null)[]
        | {
            [key: string]: string | number | boolean | null
          }
    }
    /**
     * @description Server tool type identifier (e.g. "openrouter:web_search", "openrouter:web_fetch").
     * @type string
     */
    type: string
  }[]
}

/**
 * @description Provider-specific image configuration options. Keys and values vary by model/provider. See https://openrouter.ai/docs/guides/overview/multimodal/image-generation for more details.
 * @example {"aspect_ratio":"16:9","quality":"high"}
 * @type object
 */
export type ImageConfig = {
  [key: string]: string | number | unknown[]
}

/**
 * @example {"excluded_models":["openai/gpt-6-astra"],"id":"jev-router","models":["anthropic/*","openai/gpt-5.6-sol"]}
 * @type object
 */
export type JevRouterPlugin = {
  /**
   * @description Alias of `models`, matching the auto-router field name. Entries from both fields are combined.
   * @example ["anthropic/*"]
   * @type array | undefined
   */
  allowed_models?: string[]
  /**
   * @description Select low, medium, high, or a cost tier configured by the operator. Overrides the live-config tier and replaces the shared routing policy with that tier. Omit to use the live configuration. Model exclusions and the router kill switch still apply.
   * @pattern ^[a-z][a-z0-9_-]{0,31}$
   * @example medium
   * @type string | undefined
   */
  cost_tier?: string
  /**
   * @description Remove these models from the router. Each entry is a model slug or a wildcard pattern (e.g. "xiaomi/*"). A `~author/family-latest` alias matches every revision of that family. Up to 1024 patterns, each at most 1024 characters, with 65536 total characters across all patterns. Applied after `models`, so an excluded pattern always wins over an included one; when the lists leave no model the request can use, it fails with 404 rather than routing outside them.
   * @example ["openai/gpt-6-astra","xiaomi/*"]
   * @type array | undefined
   */
  excluded_models?: string[]
  id: 'jev-router'
  /**
   * @description Restrict the router to these models. Each entry is a model slug or a wildcard pattern (e.g. "anthropic/*"), matched against the current pool; models outside the pool are ignored. A `~author/family-latest` alias matches every revision of that family. Up to 1024 patterns, each at most 1024 characters, with 65536 total characters across all patterns. When omitted or empty, every model in the pool is a candidate; when no pool model matches, the list is ignored and the whole pool is used (`excluded_models` still apply). When no entry matches any catalog model, for example a misspelled slug, the request fails with 404 instead. `allowed_models` is an alias; entries from both fields are combined.
   * @example ["anthropic/*","openai/gpt-5.6-sol"]
   * @type array | undefined
   */
  models?: string[]
}

