/**
 * @description Event sent at the start of a streaming message
 * @example {"message":{"container":null,"content":[],"id":"msg_01XFDUDYJgAACzvnptvVoYEL","model":"claude-sonnet-4-5-20250929","role":"assistant","stop_details":null,"stop_reason":null,"stop_sequence":null,"type":"message","usage":{"cache_creation":null,"cache_creation_input_tokens":null,"cache_read_input_tokens":null,"inference_geo":null,"input_tokens":12,"output_tokens":0,"output_tokens_details":null,"server_tool_use":null,"service_tier":"standard"}},"type":"message_start"}
 * @type object
 */
export type MessagesStartEvent = {
  message: {
    /**
     * @example {"expires_at":"2026-04-08T00:00:00Z","id":"ctr_01abc","skills":null}
     * @type object
     */
    container: AnthropicContainer | null
    content: ORAnthropicContentBlock[]
    id: string
    input_transformations?: AnthropicInputTransformation[] | null
    model: string
    provider?: MessagesStartEventMessageProviderEnumKey
    role: 'assistant'
    /**
     * @description Structured information about a refusal
     * @example {"category":"cyber","explanation":"The request was refused due to policy.","type":"refusal"}
     * @type object
     */
    stop_details: AnthropicRefusalStopDetails | null
    stop_reason: unknown
    stop_sequence: unknown
    type: 'message'
    /**
     * @example {"cache_creation":{"ephemeral_1h_input_tokens":0,"ephemeral_5m_input_tokens":7381},"cache_creation_input_tokens":7381,"cache_read_input_tokens":0,"inference_geo":null,"input_tokens":100,"output_tokens":1,"output_tokens_details":null,"server_tool_use":null,"service_tier":"standard"}
     */
    usage: AnthropicUsage & {
      iterations?: AnthropicUsageIteration[]
      /**
       * @example standard
       * @type string | undefined
       */
      speed?: AnthropicSpeedKey | null
    }
  }
  type: 'message_start'
}

/**
 * @description Event sent when the message is complete
 * @example {"type":"message_stop"}
 * @type object
 */
export type MessagesStopEvent = {
  /**
   * @example {"attempt":1,"endpoints":{"available":[{"model":"openai/gpt-4o","provider":"OpenAI","selected":true}],"total":1},"generation_time":2016,"is_byok":false,"region":"iad","requested":"openai/gpt-4o","strategy":"direct","summary":"available=1, selected=OpenAI"}
   * @type object | undefined
   */
  openrouter_metadata?: OpenRouterMetadata
  type: 'message_stop'
}

/**
 * @description Union of all possible streaming events
 * @example {"delta":{"text":"Hello","type":"text_delta"},"index":0,"type":"content_block_delta"}
 */
export type MessagesStreamEvents =
  | (MessagesStartEvent & {
      type: 'message_start'
    })
  | (MessagesDeltaEvent & {
      type: 'message_delta'
    })
  | (MessagesStopEvent & {
      type: 'message_stop'
    })
  | (MessagesContentBlockStartEvent & {
      type: 'content_block_start'
    })
  | (MessagesContentBlockDeltaEvent & {
      type: 'content_block_delta'
    })
  | (MessagesContentBlockStopEvent & {
      type: 'content_block_stop'
    })
  | (MessagesPingEvent & {
      type: 'ping'
    })
  | (MessagesErrorEvent & {
      type: 'error'
    })

/**
 * @description Function tool definition
 * @example {"description":"Get the current weather in a location","name":"get_weather","parameters":{"properties":{"location":{"description":"The city and state","type":"string"},"unit":{"enum":["celsius","fahrenheit"],"type":"string","x-speakeasy-unknown-values":"allow"}},"required":["location"],"type":"object"},"type":"function"}
 * @type object
 */
export type FunctionTool = {
  description?: string | null
  name: string
  parameters: {
    [key: string]: unknown
  } | null
  strict?: boolean | null
  type: 'function'
}

