/**
 * @description A context compaction marker with encrypted summary
 * @example {"encrypted_content":"enc_abc123...","type":"compaction"}
 * @type object
 */
export type CompactionItem = {
  encrypted_content: string
  id?: string | null
  type: 'compaction'
  [key: string]: unknown
}

/**
 * @description Asks the model to compact the preceding input into a compaction item
 * @example {"type":"compaction_trigger"}
 * @type object
 */
export type CompactionTriggerItem = {
  type: 'compaction_trigger'
}

/**
 * @description Changes reasoning effort from this point in the conversation onward without invalidating the prompt cache for the preceding items. Place it before the user message it should apply to; it stays in effect until another configuration update. Two adjacent configuration updates are rejected. Only supported by models that accept mid-conversation effort changes.
 * @example {"reasoning":{"effort":"low"},"type":"configuration_update"}
 * @type object
 */
export type ConfigurationUpdateItem = {
  id?: string | null
  /**
   * @description Reasoning settings applied from this point in the conversation onward
   * @example {"effort":"low"}
   * @type object
   */
  reasoning: ConfigurationUpdateReasoning
  type: 'configuration_update'
}

/**
 * @description A context compaction marker with an optional encrypted summary
 * @example {"encrypted_content":"enc_abc123...","type":"context_compaction"}
 * @type object
 */
export type ContextCompactionItem = {
  encrypted_content?: string | null
  id?: string | null
  type: 'context_compaction'
  [key: string]: unknown
}

export const toolCallStatus = {
  in_progress: 'in_progress',
  completed: 'completed',
  incomplete: 'incomplete',
} as const

export type ToolCallStatusKey =
  (typeof toolCallStatus)[keyof typeof toolCallStatus]

/**
 * @description A call to a custom (freeform-grammar) tool created by the model — distinct from `function_call`. Used for tools like Codex CLI's `apply_patch` whose payload is opaque text rather than JSON arguments.
 * @example {"call_id":"call-abc123","id":"ctc-abc123","input":"*** Begin Patch\n*** End Patch","name":"apply_patch","type":"custom_tool_call"}
 * @type object
 */
export type CustomToolCallItem = {
  /**
   * @description True when the model called a tool declared with `async: true` and may continue its turn before the output is returned. Return the result in a later request as a `function_call_output` with this `call_id`.
   * @example true
   * @type boolean | undefined
   */
  async?: boolean | null
  call_id: string
  id?: string | null
  input: string
  name: string
  /**
   * @description Namespace qualifier for tools registered as part of a namespace tool group (e.g. an MCP server)
   * @type string | undefined
   */
  namespace?: string | null
  status?: ToolCallStatusKey | null
  type: 'custom_tool_call'
}

/**
 * @description File input content item
 * @example {"file_id":"file-abc123","filename":"document.pdf","type":"input_file"}
 * @type object
 */
export type InputFile = {
  file_data?: string
  file_id?: string | null
  file_url?: string
  filename?: string
  type: 'input_file'
}

/**
 * @example {"call_id":"call-abc123","output":"patch applied successfully","type":"custom_tool_call_output"}
 * @type object
 */
export type OpenAIResponseCustomToolCallOutput = {
  call_id: string
  id?: string
  output:
    | string
    | (
        | (InputText & {
            type: 'input_text'
          })
        | (InputImage & {
            type: 'input_image'
          })
        | (InputFile & {
            type: 'input_file'
          })
      )[]
  type: 'custom_tool_call_output'
}

/**
 * @description The output from a custom (freeform-grammar) tool call execution. Mirrors `function_call_output` but is matched to a `custom_tool_call` rather than a `function_call`.
 * @example {"call_id":"call-abc123","id":"ctco-abc123","output":"patch applied successfully","type":"custom_tool_call_output"}
 */
export type CustomToolCallOutputItem = OpenAIResponseCustomToolCallOutput & {
  output?: string | (InputText | (InputImage & object) | InputFile)[]
}

