/**
 * @description Token usage information for the response
 * @example {"cost":0.0012,"cost_details":{"upstream_inference_cost":null,"upstream_inference_input_cost":0.0008,"upstream_inference_output_cost":0.0004},"input_tokens":10,"input_tokens_details":{"cached_tokens":0},"output_tokens":25,"output_tokens_details":{"reasoning_tokens":0},"total_tokens":35}
 */
export type Usage =
  | (OpenAIResponsesUsage & {
      /**
       * @description Cost of the completion
       *
       * Format: `double`
       * @type number | undefined
       */
      cost?: number | null
      cost_details?: {
        /**
         * @description Metered server-tool execution cost (for example, shell sandbox time) billed for this request, in USD. Matches the billed checkpoint and settlement amounts exactly. 0 when a metered server tool ran but settled at zero dollars; absent when no metered server tool ran.
         *
         * Format: `double`
         * @type number | undefined
         */
        server_tool_cost?: number | null
        /**
         * @description
         * Format: `double`
         * @type number | undefined
         */
        upstream_inference_cost?: number | null
        /**
         * @description
         * Format: `double`
         * @type number
         */
        upstream_inference_input_cost: number
        /**
         * @description
         * Format: `double`
         * @type number
         */
        upstream_inference_output_cost: number
      }
      /**
       * @description Totals across every upstream model call of a deferred-tools run. The native usage fields report only the final call; cost covers every call.
       * @example {"completion_tokens":180,"prompt_tokens":2400,"total_tokens":2580,"turns":2}
       * @type object | undefined
       */
      deferred_tools_details?: DeferredToolsDetails
      /**
       * @description Whether a request was made using a Bring Your Own Key configuration
       * @type boolean | undefined
       */
      is_byok?: boolean
      /**
       * @description Usage for server-side tool execution (e.g., web search)
       * @example {"tool_calls_executed":2,"tool_calls_requested":2,"web_search_requests":2}
       * @type object | undefined
       */
      server_tool_use_details?: ServerToolUseDetails | null
    })
  | null

