/**
 * @description Event emitted when a new output item is added to the response
 * @example {"item":{"content":[],"id":"item-1","role":"assistant","status":"in_progress","type":"message"},"output_index":0,"sequence_number":2,"type":"response.output_item.added"}
 * @type object
 */
export type OutputItemAddedEvent = {
  item:
    | (OutputMessage & {
        type: 'message'
      })
    | (OutputItemReasoning & {
        type: 'reasoning'
      })
    | (OutputItemFunctionCall & {
        type: 'function_call'
      })
    | (OutputItemCustomToolCall & {
        type: 'custom_tool_call'
      })
    | (OutputItemWebSearchCall & {
        type: 'web_search_call'
      })
    | (OutputItemFileSearchCall & {
        type: 'file_search_call'
      })
    | (OutputItemImageGenerationCall & {
        type: 'image_generation_call'
      })
    | (OutputItemApplyPatchCall & {
        type: 'apply_patch_call'
      })
    | (OutputItemCodeInterpreterCall & {
        type: 'code_interpreter_call'
      })
    | (OutputItemCompaction & {
        type: 'compaction'
      })
    | (OutputItemMcpListTools & {
        type: 'mcp_list_tools'
      })
    | (OutputItemMcpCall & {
        type: 'mcp_call'
      })
    | (OutputItemMcpApprovalRequest & {
        type: 'mcp_approval_request'
      })
  output_index: number
  sequence_number: number
  type: 'response.output_item.added'
}

