export type OpenrouterPostEmbeddingsRequestModelEnumKey =
  (typeof openrouterPostEmbeddingsRequestModelEnum)[keyof typeof openrouterPostEmbeddingsRequestModelEnum]

/**
 * @description Embeddings request input
 * @example {"dimensions":1536,"input":"The quick brown fox jumps over the lazy dog","model":"openai/text-embedding-3-small"}
 * @type object
 */
export type OpenrouterPostEmbeddingsBody = {
  /**
   * @description The number of dimensions for the output embeddings
   * @minimum 1
   * @example 1536
   * @type integer | undefined
   */
  dimensions?: number
  /**
   * @description The format of the output embeddings
   * @example float
   * @type string | undefined
   */
  encoding_format?: OpenrouterPostEmbeddingsRequestEncodingFormatEnumKey
  /**
   * @description Text, token, or multimodal input(s) to embed
   * @example The quick brown fox jumps over the lazy dog
   */
  input:
    | string
    | string[]
    | number[]
    | number[][]
    | {
        content: (
          | {
              /**
               * @minLength 1
               * @type string
               */
              text: string
              type: 'text'
            }
          | {
              image_url: {
                url: string
              }
              type: 'image_url'
            }
          | ContentPartInputAudio
          | ContentPartInputVideo
          | ContentPartInputFile
        )[]
      }[]
  /**
   * @description The type of input (e.g. search_query, search_document)
   * @example search_query
   * @type string | undefined
   */
  input_type?: string
  /**
   * @description The model to use for embeddings
   * @example openai/text-embedding-3-small
   * @type string
   */
  model: OpenrouterPostEmbeddingsRequestModelEnumKey
  /**
   * @description Provider routing preferences for the request.
   * @example {"allow_fallbacks":true}
   * @type object | undefined
   */
  provider?: ProviderPreferences | null
  /**
   * @description A unique identifier for grouping related requests (e.g., a conversation or agent workflow). Used for observability grouping in Broadcast and private logging; never sent to the provider. If provided in both the request body and the x-session-id header, the body value takes precedence. Maximum of 256 characters.
   * @maxLength 256
   * @example session-1234
   * @type string | undefined
   */
  session_id?: string
  /**
   * @description Metadata for observability and tracing. Known keys (trace_id, trace_name, span_name, generation_name, parent_span_id) have special handling. Additional keys are passed through as custom metadata to configured broadcast destinations.
   * @example {"trace_id":"trace-abc123","trace_name":"my-app-trace"}
   * @type object | undefined
   */
  trace?: TraceConfig
  /**
   * @description A unique identifier for the end-user
   * @example user-1234
   * @type string | undefined
   */
  user?: string
}

