/**
 * @description Union of all possible responses
 */
export type OpenrouterPostEmbeddingsResponse = OpenrouterPostEmbeddingsStatus200

/**
 * @description Non-streaming response from the Anthropic Messages API with OpenRouter extensions
 * @example {"container":null,"content":[{"citations":[],"text":"Hello! I'm doing well, thank you for asking.","type":"text"}],"id":"msg_01XFDUDYJgAACzvnptvVoYEL","model":"claude-sonnet-4-5-20250929","role":"assistant","stop_details":null,"stop_reason":"end_turn","stop_sequence":null,"type":"message","usage":{"cache_creation":null,"cache_creation_input_tokens":null,"cache_read_input_tokens":null,"inference_geo":null,"input_tokens":12,"output_tokens":15,"output_tokens_details":null,"server_tool_use":null,"service_tier":"standard"}}
 */
export type OpenrouterPostMessagesStatus200Json = BaseMessagesResult & {
  context_management?: {
    applied_edits: {
      type: string
      [key: string]: unknown
    }[]
  } | null
  /**
   * @example {"attempt":1,"endpoints":{"available":[{"model":"openai/gpt-4o","provider":"OpenAI","selected":true}],"total":1},"generation_time":2016,"is_byok":false,"region":"iad","requested":"openai/gpt-4o","strategy":"direct","summary":"available=1, selected=OpenAI"}
   * @type object | undefined
   */
  openrouter_metadata?: OpenRouterMetadata
  provider?: string
  safeguard_results?: AnthropicSafeguardResult[] | null
  /**
   * @example {"cache_creation":null,"cache_creation_input_tokens":null,"cache_read_input_tokens":null,"inference_geo":null,"input_tokens":100,"output_tokens":50,"output_tokens_details":null,"server_tool_use":null,"service_tier":"standard"}
   */
  usage?: AnthropicUsage & {
    /**
     * @description
     * Format: `double`
     * @type number | undefined
     */
    cost?: number | null
    /**
     * @description Breakdown of upstream inference costs
     * @example {"upstream_inference_completions_cost":0.0004,"upstream_inference_cost":null,"upstream_inference_prompt_cost":0.0008}
     * @type object | undefined
     */
    cost_details?: CostDetails | null
    deferred_tools_details?: {
      /**
       * @description Completion tokens summed over every upstream call
       * @type integer
       */
      completion_tokens: number
      /**
       * @description Prompt tokens summed over every upstream call
       * @type integer
       */
      prompt_tokens: number
      /**
       * @description Sum of the above two fields
       * @type integer
       */
      total_tokens: number
      /**
       * @description Upstream model calls the run made
       * @minimum 0
       * @type integer
       */
      turns: number
    }
    is_byok?: boolean
    iterations?: AnthropicUsageIteration[]
    /**
     * @example {"tool_calls_executed":1,"tool_calls_requested":1,"web_fetch_requests":0,"web_search_requests":0}
     * @type object | undefined
     */
    server_tool_use?: ORAnthropicServerToolUsage | null
    service_tier?: string | null
    /**
     * @example standard
     * @type string | undefined
     */
    speed?: AnthropicSpeedKey | null
  }
}

/**
 * @example {"data":{"delta":{"text":"Hello","type":"text_delta"},"index":0,"type":"content_block_delta"},"event":"content_block_delta"}
 * @type object
 */
export type OpenrouterPostMessagesStatus200EventStream = {
  /**
   * @description Union of all possible streaming events
   * @example {"delta":{"text":"Hello","type":"text_delta"},"index":0,"type":"content_block_delta"}
   */
  data: MessagesStreamEvents
  event: string
}

export type OpenrouterPostMessagesStatus200 =
  | OpenrouterPostMessagesStatus200Json
  | OpenrouterPostMessagesStatus200EventStream

